-- Simulation gates remain in force. These guards prevent legacy reference-only outcomes.
CREATE TRIGGER managed_actual_execution_packet BEFORE UPDATE ON managed_payouts WHEN NEW.status<>OLD.status AND NEW.status IN('processing','paid','failed') AND NOT EXISTS(SELECT 1 FROM payout_transfer_packets p JOIN users u ON u.id=CASE WHEN NEW.status='processing' THEN p.started_by ELSE p.recorded_by END JOIN user_roles r ON r.user_id=u.id WHERE p.managed_payout_id=NEW.id AND p.seller_id=NEW.seller_id AND p.state=NEW.status AND p.amount_paisa=NEW.amount_paisa AND u.status='active' AND r.role='super_admin') BEGIN SELECT RAISE(ABORT,'managed_payout_requires_actual_execution_packet'); END;
--> statement-breakpoint
CREATE TRIGGER fixed_actual_execution_packet BEFORE UPDATE ON managed_supplier_payments WHEN NEW.status<>OLD.status AND NEW.status IN('paid','failed') AND NOT EXISTS(SELECT 1 FROM payout_transfer_packets p JOIN managed_supplier_obligations o ON o.id=NEW.obligation_id JOIN users u ON u.id=p.recorded_by JOIN user_roles r ON r.user_id=u.id WHERE p.supplier_payment_id=NEW.id AND p.seller_id=o.seller_id AND p.state=NEW.status AND p.amount_paisa=NEW.amount_paisa AND u.status='active' AND r.role='super_admin') BEGIN SELECT RAISE(ABORT,'fixed_supplier_requires_actual_execution_packet'); END;

--> statement-breakpoint
CREATE TRIGGER registered_live_instruction_retained BEFORE UPDATE ON payouts WHEN NEW.status='rejected' AND OLD.status<>NEW.status AND EXISTS(SELECT 1 FROM payout_transfer_packets p WHERE p.registered_payout_id=NEW.id AND p.state NOT IN('void','failed')) BEGIN SELECT RAISE(ABORT,'retire_or_reconcile_original_payout_instruction_first'); END;
--> statement-breakpoint
CREATE TRIGGER managed_live_instruction_retained BEFORE UPDATE ON managed_payouts WHEN NEW.status='cancelled' AND OLD.status<>NEW.status AND EXISTS(SELECT 1 FROM payout_transfer_packets p WHERE p.managed_payout_id=NEW.id AND p.state NOT IN('void','failed')) BEGIN SELECT RAISE(ABORT,'retire_or_reconcile_original_payout_instruction_first'); END;
--> statement-breakpoint
CREATE TRIGGER fixed_live_instruction_retained BEFORE UPDATE ON managed_supplier_payments WHEN NEW.status='cancelled' AND OLD.status<>NEW.status AND EXISTS(SELECT 1 FROM payout_transfer_packets p WHERE p.supplier_payment_id=NEW.id AND p.state NOT IN('void','failed')) BEGIN SELECT RAISE(ABORT,'retire_or_reconcile_original_payout_instruction_first'); END;
